INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8afe32e9-a108-4c78-a352-7f6b05a0f4b3', '21feff02-016d-46e2-bb9d-c27495133b1b', '21. óra: Gyakorlóóra: a tanult oszthatósági szabályok alkalmazása', 'Gyakorlás, igaz-hamis állítások, halmazábrák oszthatóságra.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "05594d6e-a8e4-4f70-a044-8d9baa918a7c", "text": "Melyik szám osztható 2-vel, 3-mal és 5-tel is (azaz 30-cal)?", "type": "multiple-choice", "options": [{"id": "fb11bd54-e53e-464a-8812-157596248583", "text": "90", "isCorrect": true}, {"id": "b649e626-189b-40b4-a5ce-b3a5b871b7eb", "text": "45", "isCorrect": false}, {"id": "90926a95-e216-46eb-afb3-b21ff07fc0db", "text": "80", "isCorrect": false}, {"id": "5aead95a-fc9b-4e4b-8ba2-79cc7f82bb1d", "text": "100", "isCorrect": false}], "timeLimit": 15}, {"id": "6ba11b20-48b2-4f66-a169-8eceae9f7c82", "text": "A 180 osztható 4-gyel és 9-cel is.", "type": "true-false", "options": [{"id": "babe9c78-b1aa-4e6d-9b5b-4e30e16d460d", "text": "Igaz", "isCorrect": true}, {"id": "2dd87bc7-dff3-4fef-8f6c-2c2e8e4d6144", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cad9373e-00a7-4705-b2ec-e077b55e8355", "text": "Hány olyan szám van 1 és 100 között, ami osztható 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "262da011-db33-4155-9b63-76638169527e", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "9772f3ec-88cb-43d9-aadd-de96531d56bd", "text": "729 (7+2+9=18)", "isCorrect": true}, {"id": "a11e782f-5195-4048-b854-9f1c14168cde", "text": "721", "isCorrect": false}, {"id": "d415df66-aa5d-4f2b-b8e0-cebb9a212d0b", "text": "725", "isCorrect": false}, {"id": "243a1496-38d2-4944-b3e5-8322a4f94c59", "text": "730", "isCorrect": false}], "timeLimit": 15}, {"id": "2b000d0c-b4b9-4e50-8cce-7052ffb8883e", "text": "Ha egy szám osztható 10-zel, akkor 5-tel is osztható.", "type": "true-false", "options": [{"id": "108c8890-3c95-4380-9f05-4bdc0359d861", "text": "Igaz", "isCorrect": true}, {"id": "55490fff-357b-416c-8ee1-0557b5e4f4c7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "244409e2-74f0-49fb-ac66-b13f3ac7491c", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 5-tel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "523fdda0-749c-4d69-958d-f113207d6452", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 3-mal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "102"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c40d0436-265b-49d1-80a5-cddec9312728', '21feff02-016d-46e2-bb9d-c27495133b1b', '22. óra: Többszörös, közös többszörös', 'Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "017c570c-6728-43b5-9e71-4da86a08443d", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "156b48fd-8c52-4828-80f6-c97ebe44967e", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "88daa00c-8834-47de-a515-33e2e12b8726", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "b59d3622-561b-45e8-aad2-fd50118cbcfe", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "c2ac71aa-f7c7-4399-82a3-03558e0f0652", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "70f834f5-2ae1-415e-bc30-392b07a645dc", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "31242aae-7207-445b-91c2-c9020570a44f", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "c3c957b2-2288-4cbf-9973-bc6770a733cc", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "78453280-39b5-4f9b-965b-e8bdb0fd658e", "text": "Igaz", "isCorrect": true}, {"id": "11053766-2cfa-4fd7-9f57-d3974cf29433", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "19e09519-0112-456e-8268-ba50fbd264fd", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "fd922837-87c2-49b1-aaa6-39a239e97fb7", "text": "Igaz", "isCorrect": true}, {"id": "37c260b2-0c2a-4d30-aa02-ab95b9964502", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c87d883-56b3-48a0-b827-e72963ca3e0c", "text": "Mennyi a 6 és 8 legkisebb közös többszöröse?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "834c2512-d739-477a-9a3f-83276bacd873", "text": "Melyik szám közös többszöröse a 2-nek és a 5-nek?", "type": "multiple-choice", "options": [{"id": "ca5326c3-f9ca-4478-816d-c99eec9c029c", "text": "10", "isCorrect": true}, {"id": "63f2817c-c2ad-4e70-a882-6d46c2e11085", "text": "15", "isCorrect": false}, {"id": "f1f5bc04-b141-45b5-8274-707e7b574a45", "text": "8", "isCorrect": false}, {"id": "62b9355c-297d-41d8-88e3-042f9c2fda36", "text": "12", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e1e876f1-7e2d-42b4-a249-b01530d408a9', '21feff02-016d-46e2-bb9d-c27495133b1b', '23. óra: Osztó, közös osztó', 'Közös osztók, legnagyobb közös osztó (lnko) és törtek egyszerűsítése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "7160bef0-1ff9-42ed-8b74-cc8f5b695671", "text": "Mit jelent két szám legnagyobb közös osztója (lnko)?", "type": "multiple-choice", "options": [{"id": "2fb8fac9-f808-43a0-9581-9117b339d95c", "text": "A legnagyobb olyan pozitív számot, amely mindkét számot osztja", "isCorrect": true}, {"id": "2dbe2dee-7762-4a77-8d3b-49bb3886fe12", "text": "A két szám összege", "isCorrect": false}, {"id": "7721a9f8-ee37-4566-a95b-3c81261f9cef", "text": "A legkisebb többszöröst", "isCorrect": false}, {"id": "ac03629b-c5d6-4b91-bdbf-599dea23f442", "text": "Az 1-et mindig", "isCorrect": false}], "timeLimit": 15}, {"id": "ccc882f8-55fc-478c-ae43-dea6da3d1d2f", "text": "Mennyi a 12 és 18 legnagyobb közös osztója, lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "e62f6ffb-c173-4725-b3d3-2d0dfa1dc47f", "text": "Mennyi a 15 és 25 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "44b3ee5d-cd17-43a8-8e9b-8d961627b939", "text": "Két számot relatív prímeknek nevezünk, ha a legnagyobb közös osztójuk 1.", "type": "true-false", "options": [{"id": "e49ea2cd-9707-49b1-acf3-7353afaf0bae", "text": "Igaz", "isCorrect": true}, {"id": "4f3f649c-4f5f-4510-976f-fc39fe3453e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "06d683e6-2b58-470b-ac91-32bdaec355c8", "text": "A 8 és 9 relatív prímek (lnko(8,9) = 1).", "type": "true-false", "options": [{"id": "2559b7e7-41f9-412f-9e22-623a03a4da40", "text": "Igaz", "isCorrect": true}, {"id": "ccdf4c6e-7074-4512-b0ce-9eb783e3733a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "134b0106-b890-42f9-bb51-bbaed7bbe208", "text": "A legnagyobb közös osztóval egyszerűsítve a törtet a legegyszerűbb alakot kapjuk.", "type": "true-false", "options": [{"id": "18ef20a8-3f0c-4131-af59-5cd2b3d159d4", "text": "Igaz", "isCorrect": true}, {"id": "e85264a2-7ebd-43f1-85e6-fec9180ec631", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f1fa5c08-0002-458c-a197-5c203f9d9f52", "text": "Mennyi a 20 és 30 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('71da5982-5a38-4e1c-b4fa-2aa9c64600fd', '21feff02-016d-46e2-bb9d-c27495133b1b', '24. óra: Összefoglalás', 'A tanult fogalmak ismétlése, rendszerezése az egész számok és oszthatóság témakörből.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "3cadb805-408e-4983-9e20-0a5bab96d5eb", "text": "Mennyi (-12) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "f3301f24-e289-4454-943a-febef4b5daaf", "text": "Mennyi lkkt(6, 9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "f161df02-e1b0-455c-bbe7-99ef0d8fa608", "text": "Mennyi lnko(24, 36)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "893eabbd-da4b-4930-b294-1d3ef2e6577a", "text": "A 135 osztható 5-tel és 9-cel is.", "type": "true-false", "options": [{"id": "06fb58e1-badf-4bb0-9c54-9c51f6aa4e7f", "text": "Igaz", "isCorrect": true}, {"id": "28d4cdd8-d3c8-4de2-8f17-1d7f198fe831", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "76836a5a-7754-4757-a477-cab7c17c0f08", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "b7f42563-f1ce-4d91-9253-c7e8476528a9", "text": "Igaz", "isCorrect": true}, {"id": "4bff04c7-81c8-4ccf-baa9-88a767269bc4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "131d9c02-1f03-4c26-a487-e0679e10c788", "text": "Mennyi (-50) : (+10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "9c8a155f-aa8c-40f9-9cca-e87f620943f4", "text": "Melyik szám osztható 4-gyel?", "type": "multiple-choice", "options": [{"id": "39785d21-65f4-4bae-8a0e-0f593b86efcb", "text": "524", "isCorrect": true}, {"id": "fa54dfb3-0290-449c-92ca-0b3f74e38c4f", "text": "522", "isCorrect": false}, {"id": "007bdfb3-d807-4b41-9a63-b2e4f9c9978a", "text": "521", "isCorrec