], "timeLimit": 15}, {"id": "af2493a2-f9c2-4ac5-809b-124002826345", "text": "Mennyi lkkt(4, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('80eea3a5-4e1d-4bc5-8f1b-9390ceda70a7', '21feff02-016d-46e2-bb9d-c27495133b1b', '26. óra: Témazáró dolgozat', 'Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "2261b5af-317e-41a8-8ef8-71e37a457544", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "6ae86df7-ea09-490f-b21d-7ce10cce0125", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "110afed1-fb19-4755-996b-13bb1aa959b1", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "5a30b3fe-537d-4d49-9df6-5de4a898d19d", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "ee785a52-8972-47f3-9bcb-131c0589169a", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "85148df1-1924-470e-9b2a-58c42d64cd7f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eda54de3-848e-4ede-b97c-aed03c20a83f", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "08df5a4c-9d14-4652-b659-bbbb350accaf", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "3d5ae1dd-27fc-4b70-b609-7dc7eb4a43ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f6a542e9-fe79-4b40-a992-a274f778782f", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "8e978826-f97e-4a8c-988c-9e3a36af64d2", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ee767448-63f8-45c0-909a-5c7a12e80de8", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "951b3b36-614d-4377-b01c-e7c9ba724b00", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4d02cc23-c420-4340-a808-b8899c2b291b", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "acf3ff89-a12e-4691-a7a8-f022b5d1e72c", "text": "Igaz", "isCorrect": true}, {"id": "f580fa98-d20a-4034-a38c-91b06522e2be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bb904207-8008-4d04-83d4-89f2277fffce', '21feff02-016d-46e2-bb9d-c27495133b1b', '27. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "d9168283-f1ec-4fee-b3f2-f254acf1bead", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "017e2266-9373-497a-96de-80fdb72bc13c", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "e0837a8d-2747-4817-a43f-f455de6e84dc", "text": "A számok leírása", "isCorrect": false}, {"id": "155868d1-2f40-43de-beae-9029c4ef1da8", "text": "A vonalzó használata", "isCorrect": false}, {"id": "1749b4b2-b531-4589-9f3a-6962605e9e2a", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "d2cbf2ce-7594-4ca3-ae42-9ebab7404049", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "2733762c-543c-484f-82af-e5fadaa36984", "text": "Igaz", "isCorrect": true}, {"id": "0671c5b7-e093-49ef-b826-7d6faecc3c4e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "afc46d04-4a89-45bd-90e3-e77669ab6dd1", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "0ae0267b-5369-4875-80d6-aeb88247fe5c", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "c53805c7-1887-480c-9615-44ab570cc7db", "text": "Igaz", "isCorrect": true}, {"id": "5748e00f-fe6e-4138-b6c4-1abaf71fb797", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8e94800f-ae85-46d4-a321-2d44d2adddcc", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0a1e934a-e581-4af8-8d58-5806899746cd", "text": "A dolgozatok áttekintése segít a hiányosságok pótlásában.", "type": "true-false", "options": [{"id": "ba486993-9e16-47b6-b327-36063f958a99", "text": "Igaz", "isCorrect": true}, {"id": "9d8aa51f-b425-4f27-ade5-15c39296511c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "93cb0890-13b5-4904-809c-fa071f4af0b7", "text": "Mennyi lnko(10, 15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a51d1fc3-4176-4cc1-8cbd-98871deb31a8', '21feff02-016d-46e2-bb9d-c27495133b1b', '28. óra: Mit tanultunk a törtekről? Ismétlés', 'Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "f4dc438e-7dbc-4a5a-8279-9b466b5f4904", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "01bbb086-eb9c-471f-b4ac-6c2ba051e9ce", "text": "Számláló", "isCorrect": true}, {"id": "bcf62aea-bf7a-416e-ba54-f8a236cba7a7", "text": "Nevező", "isCorrect": false}, {"id": "5898b51d-0f19-464e-bc93-352204d40546", "text": "Törtvonal", "isCorrect": false}, {"id": "86d67d63-85f7-4ce5-9982-baa024d27665", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "a140c601-33f8-427d-9c62-0299d15068f0", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "6a4bd9f2-c3fc-4f93-8d31-25fa40f9a0bc", "text": "Nevező", "isCorrect": true}, {"id": "8ac61fd4-e601-4686-be75-c5ebf1de9d7f", "text": "Számláló", "isCorrect": false}, {"id": "21cf0147-1b8d-497b-8036-7eb395aa4cc2", "text": "Osztó", "isCorrect": false}, {"id": "086391c7-6dc6-4635-8316-1d5b7036451c", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "f9e76c9f-c223-4a29-a75c-453ecdd96254", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "6405a2bc-75bb-40ef-820e-bb7dfa06cb26", "text": "6/8", "isCorrect": true}, {"id": "1c1b990b-9a87-4e8d-af8c-2421ebc61cf9", "text": "5/6", "isCorrect": false}, {"id": "12a90cac-2918-4953-9f57-37eb460cb251", "text": "3/8", "isCorrect": false}, {"id": "f66b2bf3-8522-4e4e-9e27-8a353b15f264", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "16e10901-477d-4ad1-92d4-9280a35fd0b8", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "d8297d42-81bd-445a-ab0e-95e6cb51ee8a", "text": "3/5", "isCorrect": true}, {"id": "cffc13d3-571a-4325-a95e-9364dcf91ff7", "text": "3/10", "isCorrect": false}, {"id": "e2991339-3ab1-400f-a525-c6fc38def647", "text": "6/5", "isCorrect": false}, {"id": "a17f0d77-d46a-4cde-add2-06fa49d449b0", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "7cb0f3aa-abf6-4532-af9e-e29a80378ae5", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "d0a6decb-3703-444d-9c89-58468a8fd914", "text": "Igaz", "isCorrect": true}, {"id": "5900a4f2-d6f8-4060-a1c4-7b562c1a29d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c16d3438-7124-434f-b772-fd28f5e0629f", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e4f50a56-c519-4200-a144-ad3f05f9bb05", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "1b50ec75-eed9-4d4c-bc1c-7049658f1453", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "53a85136-f015-42d2-a1aa-06dd1535062f", "text": "2/6", "isCorrect": false}, {"id": "7b6db65b-a03a-44bd-8d98-e0683f986504", "text": "2/4", "isCorrect": false}, {"id": "0f089591-7f32-423f-9604-573b611d8d60", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4c4d96a9-4a9e-4ae1-8282-39309414a10b', '21feff02-016d-46e2-bb9d-c27495133b1b', '29. óra: Mit tanultunk a törtekről? Ismétlés II.', 'Összeadás és kivonás azonos és különböző nevezőjű törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "eb1649e7-667b-4b7c-84c4-86b676bccc7c", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "a694ef17-ce42-4ca9-9c3a-8f9356f6878d", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "44a5e87c-15a6-4523-87b6-1c100cf14dd9", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "899c36f2-c3aa-4e39-a916-b2345ab1a883", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "20aa683a-fdc6-47ff-b991-96dbd53e6025", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "03e9eaf6-070a-470d-95dd-d0886246001e", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "32bc80ed-eec3-4a46-8eef-de3b3c7da49a", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "9801bdb7-a270-4c1c-bd46-8db3525fafb6", "text": "2/9", "isCorrect": false}, {"id": "0eb66c48-241b-4151-aa28-871791544cdc", "text": "1/9", "isCorrect": false}, {"id": "00753e86-fc69-4b3b-a34c-96409caf4a61", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "8384fcf2-43bf-4183-9d22-3233b2520ca4", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "754b7a48-97bb-4ff8-9726-59b85c0110a2", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "99f69e91-30bf-4549-8ce6-a4f9ae49eac0", "text": "2/0", "isCorrect": false}, {"id": "0938b6ce-4d2d-4748-8d90-43251881f6ae", "text": "8/8", "isCorrect": false}, {"id": "3a005279-77cb-489a-8983-348bbca6bb31", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "eb1225c3-11a6-4b44-8b2d-29a