INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a3e2cb5e-b015-409a-8996-a43d89faa23a', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "9cd05f23-dd69-449d-984e-923c651632d1", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "d33e7b9e-2568-4790-971e-796428bb709e", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "d4d003d9-b094-4dda-8eb9-b7cc8d398939", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "9fdba903-68b5-4ea0-8acf-749673d207c9", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "52d3b36b-df3f-4f8f-8ade-15e4f8d05c62", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "b514c119-f960-4c07-ad02-83741b3ba1e0", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "3f2114e0-a0ed-4822-899a-552862d5c8ef", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "bfa15470-5de2-48fb-81be-269d48369736", "text": "5/8", "isCorrect": false}, {"id": "5f2cea46-8614-4069-8907-4e0f75af1c6c", "text": "6/8", "isCorrect": false}, {"id": "96708959-0068-4388-8d6c-462c735b4995", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "155932a2-276e-4779-973f-906885dd729e", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "7d52a22f-4af9-403d-8b50-320ebcacbb86", "text": "4/3", "isCorrect": true}, {"id": "f3620330-85e0-40a1-910b-a43e6a190239", "text": "-3/4", "isCorrect": false}, {"id": "a27ea4e5-dad9-4435-8a87-cadcc7dbd95d", "text": "1/4", "isCorrect": false}, {"id": "c4add732-a6a1-46c5-8a77-7422c10c297e", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "170dd4af-70d0-4d0d-805c-e6bde7af47d9", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "3740a17b-f8d5-4ec0-b4d3-9fb24b1f18ff", "text": "Igaz", "isCorrect": true}, {"id": "192b7fc9-777e-44fb-b0db-9aa928d5b9c7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c4932c5e-244d-47c3-833e-9a015631c9f9", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "be3bdef3-f2cc-414f-aed9-e0faf1c53ff8", "text": "1/5", "isCorrect": true}, {"id": "9c373328-efc8-42e5-aff5-89b79ba222c2", "text": "-5", "isCorrect": false}, {"id": "451e91fb-170e-4951-8ad3-0618145d4854", "text": "5/1", "isCorrect": false}, {"id": "a2fbe2c2-ea38-46bb-874f-298d1c825f93", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "f0340b02-e091-492e-bdfd-f4516adafb94", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "90660ce2-45bb-4e9f-a57f-6be28155ac00", "text": "Igaz", "isCorrect": true}, {"id": "80a65589-c03b-4849-a442-9326871a87d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56ca9ff3-40b8-4274-995f-4bcde721dd7f", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "8c882412-1ee4-4078-9abb-641685d50e7f", "text": "1/6", "isCorrect": true}, {"id": "927bd290-b9c5-4f6a-9cb2-819ddd3cb60a", "text": "2/5", "isCorrect": false}, {"id": "0bab7c1f-5ae9-4a46-be2f-19f3782031fd", "text": "1/5", "isCorrect": false}, {"id": "6b0ad9e4-292c-448b-95db-a961219a32a1", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;